class SearchIndex:
    """In-memory inverted index over note bodies."""

    def __init__(self):
        self.postings = {}

    def add(self, note_id, body):
        """Add one note body to the inverted index."""
        for token in tokenize(body):
            self.postings.setdefault(token, set()).add(note_id)

def add(self, note_id, body):
    """Add one note body to the inverted index."""
    for token in tokenize(body):
        self.postings.setdefault(token, set()).add(note_id)

def tokenize(text):
    """Split text into lowercase word tokens for ranking."""
    return [token.lower() for token in text.split() if token]

class NoteStore:
    """Durable storage for notes, backed by SQLite."""

    def __init__(self, connection):
        self.connection = connection

    def save_note(self, note_id, body, author):
        """Insert or replace one note row and return the stored note id."""
        self.connection.execute(
            "INSERT OR REPLACE INTO notes (note_id, body, author) VALUES (?, ?, ?)",
            (note_id, body, author),
        )
        return note_id

    def load_note(self, note_id):
        """Read a single note row by note id, or None when it is missing."""
        row = self.connection.execute(
            "SELECT note_id, body, author FROM notes WHERE note_id = ?", (note_id,)
        ).fetchone()
        return dict(row) if row else None

